from model import Summary


def run(data, limit):
    frames = []
    offset = 0

    while offset < len(data):
        start = offset
        length = data[offset]

        if length > limit:
            return Summary(frames, start, 3)

        payload_start = offset + 1
        payload_end = payload_start + length
        checksum_offset = payload_end

        if checksum_offset >= len(data):
            return Summary(frames, start, 1)

        payload = data[payload_start:payload_end]
        if data[checksum_offset] != sum(payload) % 256:
            return Summary(frames, start, 2)

        frames.append(payload)
        offset = checksum_offset + 1

    return Summary(frames, len(data), 0)

